mapper.select:
SELECT dc.id, dc.category_name, r.name AS restaurant_name, dc.update_time, (SELECT MIN(d.create_time) FROM dish d WHERE d.category_id = dc.id AND d.is_deleted = 0) AS dish_create_time FROM dish_category dc LEFT JOIN restaurant r ON dc.restaurant_id = r.id WHERE dc.is_deleted = 0
AND dc.category_name LIKE CONCAT('%', #{categoryName}, '%')
AND dc.restaurant_id = #{restaurantId}
AND dc.status = #{status}
ORDER BY r.create_time DESC, dc.sort_num ASC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM dish_category dc LEFT JOIN restaurant r ON dc.restaurant_id = r.id WHERE dc.is_deleted = 0
AND dc.category_name LIKE CONCAT('%', #{categoryName}, '%')
AND dc.restaurant_id = #{restaurantId}
AND dc.status = #{status}
